# get_charge handler (from an AI assistant)
def get_charge(acct, charge_id):
    c = db.load(charge_id)
    if acct.version < "2023-01-01":
        return {"paid": c.ok}
    if acct.version < "2024-04-01":
        return {"status": c.status}
    return {"status": c.status, "cents": c.cents}
